#include "image.hpp"
#include "image_validate.h"

#include <stdexcept>
#include <utility>

/* ------------------------------------------------------------------ */
/* 256 bit row <-> 64 lowercase hex digits, most significant first     */
/* ------------------------------------------------------------------ */

std::string image_word_hex(const Row256& bits) {
    static const char* digits = "0123456789abcdef";
    std::string out(64, '0');
    for (int i = 0; i < 64; ++i) {
        unsigned v = 0;
        for (int b = 0; b < 4; ++b) v |= bits[4 * i + b] ? (1u << b) : 0u;
        out[63 - i] = digits[v];
    }
    return out;
}

Row256 image_word_from_hex(const std::string& text) {
    if (text.size() != 64) throw std::runtime_error("word length");
    Row256 out;
    for (int i = 0; i < 64; ++i) {
        char c = text[63 - i];
        int v;
        if (c >= '0' && c <= '9') v = c - '0';
        else if (c >= 'a' && c <= 'f') v = c - 'a' + 10;
        else throw std::runtime_error("word hex");
        for (int b = 0; b < 4; ++b) out[4 * i + b] = ((v >> b) & 1) != 0;
    }
    return out;
}

/* ------------------------------------------------------------------ */
/* Loaded image: all-or-nothing commit, then detached lookups          */
/* ------------------------------------------------------------------ */

bool MemoryImage::load(const ImageData& proposed) {
    ParsedImage parsed;
    if (!validate_image(proposed, parsed)) return false;
    data_ = proposed;
    parsed_ = std::move(parsed);
    valid_ = true;
    return true;
}

namespace {
int32_t find_front(const std::vector<std::pair<uint64_t, int32_t> >& v, uint64_t key) {
    size_t lo = 0, hi = v.size();
    while (lo < hi) {
        size_t mid = (lo + hi) / 2;
        if (v[mid].first < key) lo = mid + 1;
        else hi = mid;
    }
    if (lo < v.size() && v[lo].first == key) return v[lo].second;
    return -1;
}
} /* namespace */

nexthop_t MemoryImage::lookup(ip6_t ip) const {
    if (!valid_) return LPM_INVALID_NH;
    u128_t a = scamp_make128(ip.hi, ip.lo);
    int32_t node = find_front(parsed_.front64, ip.hi);
    if (node < 0) node = find_front(parsed_.front16, ip.hi >> 48);
    if (node < 0) node = parsed_.root;
    if (node < 0) return LPM_INVALID_NH;

    const std::vector<uint32_t>& ni = data_.nexthops;
    for (;;) {
        const ImageQueryNode& n = parsed_.nodes[node];
        if (n.type <= TYPE3) {
            uint32_t key = scamp_bits(a, n.depth, 6);
            int32_t child = -1;
            for (uint8_t i = 0; i < n.nchild; ++i) {
                if (parsed_.child_key[n.child_start + i] == key) {
                    child = parsed_.child_node[n.child_start + i];
                    break;
                }
            }
            if (child >= 0) { node = child; continue; }
            int top = 128 - static_cast<int>(n.depth);
            if (top > 5) top = 5;
            for (int l = top; l >= 0; --l) {
                uint32_t v = scamp_bits(a, n.depth, l);
                uint64_t pos = (1ULL << l) + v;
                if (n.pattern & (1ULL << pos)) {
                    uint64_t below = (pos == 0) ? 0 : ((1ULL << pos) - 1);
                    uint32_t off = scamp_popcount64(n.pattern & below);
                    return ni[n.ni_base + off];
                }
            }
        } else {
            int best = -1;
            for (int i = 0; i < n.ninl; ++i) {
                if (scamp_mask(a, n.inl_len[i]) == n.inl_addr[i]) {
                    if (best < 0 || n.inl_len[i] > n.inl_len[best]) best = i;
                }
            }
            if (best >= 0) return n.inl_hop[best];
        }
        if (n.bmp == SCAMP_BMP_NULL) return LPM_INVALID_NH;
        return static_cast<nexthop_t>(n.bmp);
    }
}
